199  hb_subset_plan_create (hb_face_t           *face,
   200                         hb_subset_input_t   *input)
   201  {
   202    hb_subset_plan_t *plan = hb_object_create<hb_subset_plan_t> ();
   203
   204    plan->drop_hints = input->drop_hints;
   205    plan->drop_layout = input->drop_layout;
   206    plan->desubroutinize = input->desubroutinize;
   207    plan->retain_gids = input->retain_gids;
   208    plan->unicodes = hb_set_create ();
   209    plan->name_ids = hb_set_reference (input->name_ids);
   210    /* TODO Clean this up... */
   211    if (hb_set_is_empty (plan->name_ids))
   212      hb_set_add_range (plan->name_ids, 0, 0x7FFF);
   213    plan->source = hb_face_reference (face);
   214    plan->dest = hb_face_builder_create ();
   215    plan->codepoint_to_glyph = hb_map_create ();
   216    plan->glyph_map = hb_map_create ();
   217    plan->reverse_glyph_map = hb_map_create ();
   218    plan->_glyphset = _populate_gids_to_retain (face,
   219                                                input->unicodes,
   220                                                input->glyphs,
   221                                                !plan->drop_layout,
   222                                                plan->unicodes,
   223                                                plan->codepoint_to_glyph);
   224
   225    _create_old_gid_to_new_gid_map (face,
   226                                    input->retain_gids,
   227                                    plan->_glyphset,
   228                                    plan->glyph_map,
   229                                    plan->reverse_glyph_map,
   230                                    &plan->_num_output_glyphs);
   231
   232    return plan;
   233  }
