   235  /**
   236   * hb_subset_plan_destroy:
   237   *
   238   * Since: 1.7.5
   239   **/
   240  void
   241  hb_subset_plan_destroy (hb_subset_plan_t *plan)
   242  {
   243    if (!hb_object_destroy (plan)) return;
   244
   245    hb_set_destroy (plan->unicodes);
   246    hb_set_destroy (plan->name_ids);
   247    hb_face_destroy (plan->source);
   248    hb_face_destroy (plan->dest);
   249    hb_map_destroy (plan->codepoint_to_glyph);
   250    hb_map_destroy (plan->glyph_map);
   251    hb_map_destroy (plan->reverse_glyph_map);
   252    hb_set_destroy (plan->_glyphset);
   253
   254    free (plan);
   255  }
